# lifeboat: exponential backoff + model fallback
import time
from redwood import RedwoodClient

client = RedwoodClient(api_key="$REDWOOD_KEY")

def request_with_lifeboat(prompt):
    backoff = 0.5
    for attempt in range(5):
        resp = client.generate(prompt, model="large-v1")
        if resp.status_code == 200:
            return resp
        if resp.status_code == 429:
            # Backoff + jitter
            time.sleep(backoff * (0.8 + 0.4 * attempt))
            backoff = min(backoff * 2, 8)
            continue
        # for timeouts, try a smaller window
        if resp.status_code == 504 and attempt == 2:
            return client.generate(prompt, model="small-llm-v1", max_tokens=256)
    raise RuntimeError("request failed after retries")
```
Sasha (devex): looks good. nits: use client.generate(..., timeout=10) instead of raw http timeout example; and show an example of honoring Retry-After: if header present, sleep that long plus jitter.
Ana (docs): updated in PR to include header honoring. also added node snippet. node snippet:```js
// node lifeboat example
const {RedwoodClient} = require('@redwood/inference');
const client = new RedwoodClient({ apiKey: process.env.REDWOOD_KEY });

async function lifeboat(prompt) {
  let backoff = 500; // ms
  for (let i = 0; i < 5; i++) {
    try {
      const res = await client.generate({ model: 'large-v1', prompt, timeout: 10000 });
      if (res.ok) return res;
      if (res.status === 429) {
        const ra = res.headers.get('retry-after');
        const wait = ra ? (parseInt(ra) * 1000 + Math.random() * 200) : backoff;
        await new Promise(r => setTimeout(r, wait));
        backoff = Math.min(backoff * 2, 8000);
        continue;
      }
    } catch (e) {
      // on socket/timeouts, try a smaller model once
      if (i === 2) return client.generate({ model: 'small-llm-v1', prompt, max_tokens: 256 });
    }
  }
  throw new Error('lifeboat failed');
}
```
